package org.overengineer.bettacraft.decor;

import org.overengineer.bettacraft.config.Features;
import org.overengineer.bettacraft.config.Feature;
import java.util.Locale;
import net.minecraft.resources.Identifier;
import org.overengineer.bettacraft.BettaCraft;

/**
 * The decoration structures (PLAN 7.3). Each is a vanilla-block structure template in
 * {@code data/bettacraft/structure/decor/<name>.nbt} (generated by {@code tools/assetgen/decor.py}); the size is the
 * footprint x height x depth in blocks, i.e. in tank pixels at interior scale 16.
 */
public enum DecorType {
    CASTLE(8, 12, 8),
    /** M21.5: the detailed versions (the small old ones: {@code _small}, with features.decor.detailed off). */
    SHIPWRECK(13, 10, 5),
    DINO_SKULL(12, 8, 6),
    VOLCANO(7, 6, 7),
    DRIFTWOOD(6, 3, 3),
    STONES(3, 2, 3),
    MOSS_BALL(1, 1, 1),
    HAMMOCK(3, 6, 2),
    ALMOND_LEAF(3, 1, 2),
    CAVE(6, 5, 4),
    /** M19: a clay tube for the plecos to breed in (blocks {@code bettacraft:spawning_cave}). */
    SPAWNING_CAVE(12, 6, 6),
    /** M19: green wool strands on a stone, for the egg scatterers (blocks {@code bettacraft:spawning_mop}). */
    SPAWNING_MOP(5, 10, 5),
    // M28 part c (appended: the item ids come from the names, the order only sorts them)
    /** A rowing boat keel up, a low cave under it for catfish. */
    ROWING_BOAT(10, 5, 8),
    /** The bow of a sailing ship; a clay pipe in its hold is a spawning cave for plecos. */
    SHIP_BOW(14, 11, 10),
    /** Holey limestone (calcite, dripstone): hardens the water like other limestone. */
    HOLEY_ROCK(7, 5, 6),
    SLATE_CAVE(8, 5, 6),
    /** Grey rocks with calcite veins (they harden the water a little). */
    SEIRYU_STONE(8, 9, 6),
    /** Ohko: terracotta (shelter for young shrimp). */
    DRAGON_STONE(8, 6, 6),
    LAVA_ROCK(6, 5, 5),
    /** Roots of wood (logs and mangrove roots lower the pH like driftwood). */
    MANGROVE_ROOT(7, 7, 7),
    SPIDERWOOD(8, 9, 8),
    BOGWOOD_BRIDGE(8, 5, 4),
    COCONUT_CAVE(6, 3, 6),
    /** Two clay tubes: each a spawning cave for plecos. */
    CLAY_TUBES(13, 6, 9),
    /** Thin terracotta tubes: shelter for young shrimp. */
    SHRIMP_TUBES(6, 6, 5),
    RUIN_COLUMN(7, 9, 4),
    DIVER_HELMET(7, 8, 7),
    /** With an air stone among its coins: bubbles when an air pump drives it. */
    TREASURE_CHEST(6, 5, 6),
    // M49 part b: the brackish water theme
    /** Tall mangrove stilt roots that stand out of the water of a paludarium (mudskippers climb on them). */
    MANGROVE_STILT_ROOTS(14, 18, 10);

    public final int sizeX, sizeY, sizeZ;

    DecorType(int sizeX, int sizeY, int sizeZ) {
        this.sizeX = sizeX;
        this.sizeY = sizeY;
        this.sizeZ = sizeZ;
    }

    public String id() {
        return name().toLowerCase(Locale.ROOT);
    }

    /** Item id: {@code bettacraft:decor_<name>}. */
    public String itemId() {
        return "decor_" + id();
    }

    /** M28: the new decorations have a line of their own in the tooltip (what they do in a tank). */
    public boolean hasHint() {
        return ordinal() >= ROWING_BOAT.ordinal();
    }

    public Identifier structure() {
        boolean small = (this == SHIPWRECK || this == DINO_SKULL) && !Features.enabled(Feature.DETAILED_DECOR);
        return BettaCraft.id("decor/" + id() + (small ? "_small" : ""));
    }
}
